import{_ as t,o,c as e,a4 as i}from"./chunks/framework.DzALyu-k.js";const h=JSON.parse('{"title":"Info studenti","description":"","frontmatter":{},"headers":[],"relativePath":"info.md","filePath":"info.md"}'),n={name:"info.md"};function r(l,a,s,c,u,p){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="info-studenti" tabindex="-1">Info studenti <a class="header-anchor" href="#info-studenti" aria-label="Permalink to &quot;Info studenti&quot;">​</a></h1><p>Per i laboratori ogni partecipante ha a disposizione un account e un ambiente preparati apposta per il corso. In questa pagina trovi cosa ricevi e cosa succede a fine corso.</p><h2 id="cosa-ricevi" tabindex="-1">Cosa ricevi <a class="header-anchor" href="#cosa-ricevi" aria-label="Permalink to &quot;Cosa ricevi&quot;">​</a></h2><h3 id="un-account-dedicato" tabindex="-1"><span class="icon f-agents"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M224,128a95.76,95.76,0,0,1-31.8,71.37A72,72,0,0,0,128,160a40,40,0,1,0-40-40,40,40,0,0,0,40,40,72,72,0,0,0-64.2,39.37h0A96,96,0,1,1,224,128Z" opacity="0.2"></path><path d="M128,24A104,104,0,1,0,232,128,104.11,104.11,0,0,0,128,24ZM74.08,197.5a64,64,0,0,1,107.84,0,87.83,87.83,0,0,1-107.84,0ZM96,120a32,32,0,1,1,32,32A32,32,0,0,1,96,120Zm97.76,66.41a79.66,79.66,0,0,0-36.06-28.75,48,48,0,1,0-59.4,0,79.66,79.66,0,0,0-36.06,28.75,88,88,0,1,1,131.52,0Z"></path></svg></span> Un account dedicato <a class="header-anchor" href="#un-account-dedicato" aria-label="Permalink to &quot;&lt;span class=&quot;icon f-agents&quot;&gt;&lt;svg aria-hidden=&quot;true&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot; viewBox=&quot;0 0 256 256&quot; fill=&quot;currentColor&quot;&gt;&lt;path d=&quot;M224,128a95.76,95.76,0,0,1-31.8,71.37A72,72,0,0,0,128,160a40,40,0,1,0-40-40,40,40,0,0,0,40,40,72,72,0,0,0-64.2,39.37h0A96,96,0,1,1,224,128Z&quot; opacity=&quot;0.2&quot;/&gt;&lt;path d=&quot;M128,24A104,104,0,1,0,232,128,104.11,104.11,0,0,0,128,24ZM74.08,197.5a64,64,0,0,1,107.84,0,87.83,87.83,0,0,1-107.84,0ZM96,120a32,32,0,1,1,32,32A32,32,0,0,1,96,120Zm97.76,66.41a79.66,79.66,0,0,0-36.06-28.75,48,48,0,1,0-59.4,0,79.66,79.66,0,0,0-36.06,28.75,88,88,0,1,1,131.52,0Z&quot;/&gt;&lt;/svg&gt;&lt;/span&gt; Un account dedicato&quot;">​</a></h3><p>Ogni partecipante riceve un account Microsoft 365 personale, creato apposta per il corso. Non serve usare il proprio account aziendale e non si condividono credenziali con altri.</p><p>Al primo accesso ti verrà chiesto di registrare l&#39;autenticazione a più fattori (MFA): tieni a portata di mano lo smartphone.</p><h3 id="una-sandbox-dedicata" tabindex="-1"><span class="icon f-platform"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,48V160H179.31a8,8,0,0,0-5.66,2.34l-19.31,19.32a8,8,0,0,1-5.66,2.34H107.31a8,8,0,0,1-5.66-2.34L82.34,162.34A8,8,0,0,0,76.68,160H40V48a8,8,0,0,1,8-8H208A8,8,0,0,1,216,48Z" opacity="0.2"></path><path d="M208,32H48A16,16,0,0,0,32,48V208a16,16,0,0,0,16,16H208a16,16,0,0,0,16-16V48A16,16,0,0,0,208,32Zm0,16V152h-28.7A15.86,15.86,0,0,0,168,156.69L148.69,176H107.31L88,156.68A15.89,15.89,0,0,0,76.69,152H48V48Zm0,160H48V168H76.69L96,187.32A15.89,15.89,0,0,0,107.31,192h41.38A15.86,15.86,0,0,0,160,187.31L179.31,168H208v40Z"></path></svg></span> Una sandbox dedicata <a class="header-anchor" href="#una-sandbox-dedicata" aria-label="Permalink to &quot;&lt;span class=&quot;icon f-platform&quot;&gt;&lt;svg aria-hidden=&quot;true&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot; viewBox=&quot;0 0 256 256&quot; fill=&quot;currentColor&quot;&gt;&lt;path d=&quot;M216,48V160H179.31a8,8,0,0,0-5.66,2.34l-19.31,19.32a8,8,0,0,1-5.66,2.34H107.31a8,8,0,0,1-5.66-2.34L82.34,162.34A8,8,0,0,0,76.68,160H40V48a8,8,0,0,1,8-8H208A8,8,0,0,1,216,48Z&quot; opacity=&quot;0.2&quot;/&gt;&lt;path d=&quot;M208,32H48A16,16,0,0,0,32,48V208a16,16,0,0,0,16,16H208a16,16,0,0,0,16-16V48A16,16,0,0,0,208,32Zm0,16V152h-28.7A15.86,15.86,0,0,0,168,156.69L148.69,176H107.31L88,156.68A15.89,15.89,0,0,0,76.69,152H48V48Zm0,160H48V168H76.69L96,187.32A15.89,15.89,0,0,0,107.31,192h41.38A15.86,15.86,0,0,0,160,187.31L179.31,168H208v40Z&quot;/&gt;&lt;/svg&gt;&lt;/span&gt; Una sandbox dedicata&quot;">​</a></h3><p>Ogni utente lavora in un proprio ambiente Power Platform isolato. Agenti, flow, soluzioni e dati che crei restano solo tuoi e non interferiscono con il lavoro degli altri partecipanti.</p><p>L&#39;ambiente ha già i crediti di Copilot Studio necessari per i lab e le funzionalità in anteprima abilitate, quindi puoi seguire tutti gli esercizi senza configurazioni aggiuntive.</p><h2 id="a-fine-corso" tabindex="-1">A fine corso <a class="header-anchor" href="#a-fine-corso" aria-label="Permalink to &quot;A fine corso&quot;">​</a></h2><h3 id="tutto-cio-che-crei-resta-tuo" tabindex="-1"><span class="icon f-lifecycle"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M128,129.09V232a8,8,0,0,1-3.84-1l-88-48.18a8,8,0,0,1-4.16-7V80.18a8,8,0,0,1,.7-3.25Z" opacity="0.2"></path><path d="M223.68,66.15,135.68,18a15.88,15.88,0,0,0-15.36,0l-88,48.17a16,16,0,0,0-8.32,14v95.64a16,16,0,0,0,8.32,14l88,48.17a15.88,15.88,0,0,0,15.36,0l88-48.17a16,16,0,0,0,8.32-14V80.18A16,16,0,0,0,223.68,66.15ZM128,32l80.34,44-29.77,16.3-80.35-44ZM128,120,47.66,76l33.9-18.56,80.34,44ZM40,90l80,43.78v85.79L40,175.82Zm176,85.78h0l-80,43.79V133.82l32-17.51V152a8,8,0,0,0,16,0V107.55L216,90v85.77Z"></path></svg></span> Tutto ciò che crei resta tuo <a class="header-anchor" href="#tutto-cio-che-crei-resta-tuo" aria-label="Permalink to &quot;&lt;span class=&quot;icon f-lifecycle&quot;&gt;&lt;svg aria-hidden=&quot;true&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot; viewBox=&quot;0 0 256 256&quot; fill=&quot;currentColor&quot;&gt;&lt;path d=&quot;M128,129.09V232a8,8,0,0,1-3.84-1l-88-48.18a8,8,0,0,1-4.16-7V80.18a8,8,0,0,1,.7-3.25Z&quot; opacity=&quot;0.2&quot;/&gt;&lt;path d=&quot;M223.68,66.15,135.68,18a15.88,15.88,0,0,0-15.36,0l-88,48.17a16,16,0,0,0-8.32,14v95.64a16,16,0,0,0,8.32,14l88,48.17a15.88,15.88,0,0,0,15.36,0l88-48.17a16,16,0,0,0,8.32-14V80.18A16,16,0,0,0,223.68,66.15ZM128,32l80.34,44-29.77,16.3-80.35-44ZM128,120,47.66,76l33.9-18.56,80.34,44ZM40,90l80,43.78v85.79L40,175.82Zm176,85.78h0l-80,43.79V133.82l32-17.51V152a8,8,0,0,0,16,0V107.55L216,90v85.77Z&quot;/&gt;&lt;/svg&gt;&lt;/span&gt; Tutto ciò che crei resta tuo&quot;">​</a></h3><p>Quello che costruisci durante i lab può essere esportato liberamente, ad esempio come soluzione Power Platform, e reimportato nel tuo tenant.</p><div class="tip custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-knowledge"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M208,104a79.86,79.86,0,0,1-30.59,62.92A24.29,24.29,0,0,0,168,186v6a8,8,0,0,1-8,8H96a8,8,0,0,1-8-8v-6a24.11,24.11,0,0,0-9.3-19A79.87,79.87,0,0,1,48,104.45C47.76,61.09,82.72,25,126.07,24A80,80,0,0,1,208,104Z" opacity="0.2"></path><path d="M176,232a8,8,0,0,1-8,8H88a8,8,0,0,1,0-16h80A8,8,0,0,1,176,232Zm40-128a87.55,87.55,0,0,1-33.64,69.21A16.24,16.24,0,0,0,176,186v6a16,16,0,0,1-16,16H96a16,16,0,0,1-16-16v-6a16,16,0,0,0-6.23-12.66A87.59,87.59,0,0,1,40,104.49C39.74,56.83,78.26,17.14,125.88,16A88,88,0,0,1,216,104Zm-16,0a72,72,0,0,0-73.74-72c-39,.92-70.47,33.39-70.26,72.39a71.65,71.65,0,0,0,27.64,56.3A32,32,0,0,1,96,186v6h64v-6a32.15,32.15,0,0,1,12.47-25.35A71.65,71.65,0,0,0,200,104Zm-16.11-9.34a57.6,57.6,0,0,0-46.56-46.55,8,8,0,0,0-2.66,15.78c16.57,2.79,30.63,16.85,33.44,33.45A8,8,0,0,0,176,104a9,9,0,0,0,1.35-.11A8,8,0,0,0,183.89,94.66Z"></path></svg></span>Suggerimento</p><p>Se vuoi conservare un agente o un flow, esportalo prima della fine del corso.</p></div><h3 id="reset-degli-ambienti" tabindex="-1"><span class="icon f-risk"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M216,128a88,88,0,1,1-88-88A88,88,0,0,1,216,128Z" opacity="0.2"></path><path d="M224,128a96,96,0,0,1-94.71,96H128A95.38,95.38,0,0,1,62.1,197.8a8,8,0,0,1,11-11.63A80,80,0,1,0,71.43,71.39a3.07,3.07,0,0,1-.26.25L44.59,96H72a8,8,0,0,1,0,16H24a8,8,0,0,1-8-8V56a8,8,0,0,1,16,0V85.8L60.25,60A96,96,0,0,1,224,128Z"></path></svg></span> Reset degli ambienti <a class="header-anchor" href="#reset-degli-ambienti" aria-label="Permalink to &quot;&lt;span class=&quot;icon f-risk&quot;&gt;&lt;svg aria-hidden=&quot;true&quot; xmlns=&quot;http://www.w3.org/2000/svg&quot; viewBox=&quot;0 0 256 256&quot; fill=&quot;currentColor&quot;&gt;&lt;path d=&quot;M216,128a88,88,0,1,1-88-88A88,88,0,0,1,216,128Z&quot; opacity=&quot;0.2&quot;/&gt;&lt;path d=&quot;M224,128a96,96,0,0,1-94.71,96H128A95.38,95.38,0,0,1,62.1,197.8a8,8,0,0,1,11-11.63A80,80,0,1,0,71.43,71.39a3.07,3.07,0,0,1-.26.25L44.59,96H72a8,8,0,0,1,0,16H24a8,8,0,0,1-8-8V56a8,8,0,0,1,16,0V85.8L60.25,60A96,96,0,0,1,224,128Z&quot;/&gt;&lt;/svg&gt;&lt;/span&gt; Reset degli ambienti&quot;">​</a></h3><p>Alla chiusura dell&#39;ultima giornata ambienti e account vengono cancellati, insieme a tutto il loro contenuto.</p><div class="warning custom-block github-alert"><p class="custom-block-title"><span class="icon callout-icon f-platform"><svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor"><path d="M215.46,216H40.54C27.92,216,20,202.79,26.13,192.09L113.59,40.22c6.3-11,22.52-11,28.82,0l87.46,151.87C236,202.79,228.08,216,215.46,216Z" opacity="0.2"></path><path d="M236.8,188.09,149.35,36.22h0a24.76,24.76,0,0,0-42.7,0L19.2,188.09a23.51,23.51,0,0,0,0,23.72A24.35,24.35,0,0,0,40.55,224h174.9a24.35,24.35,0,0,0,21.33-12.19A23.51,23.51,0,0,0,236.8,188.09ZM222.93,203.8a8.5,8.5,0,0,1-7.48,4.2H40.55a8.5,8.5,0,0,1-7.48-4.2,7.59,7.59,0,0,1,0-7.72L120.52,44.21a8.75,8.75,0,0,1,15,0l87.45,151.87A7.59,7.59,0,0,1,222.93,203.8ZM120,144V104a8,8,0,0,1,16,0v40a8,8,0,0,1-16,0Zm20,36a12,12,0,1,1-12-12A12,12,0,0,1,140,180Z"></path></svg></span>Attenzione</p><p>Dopo il reset non è più possibile recuperare nulla: esporta per tempo ciò che ti interessa.</p></div>',16)])])}const g=t(n,[["render",r]]);export{h as __pageData,g as default};
